/* From Uiverse.io by aasisodiya - Tags: button */
.__UIV_SCOPE__ button {
 background-color: #eee;
 border: none;
 padding: 1rem;
 font-size: 1rem;
 width: 10em;
 border-radius: 1rem;
 color: lightcoral;
 box-shadow: 0 0.4rem #dfd9d9;
 cursor: pointer;
}

.__UIV_SCOPE__ button:active {
 color: white;
 box-shadow: 0 0.2rem #dfd9d9;
 transform: translateY(0.2rem);
}

.__UIV_SCOPE__ button:hover:not(:disabled) {
 background: lightcoral;
 color: white;
 text-shadow: 0 0.1rem #bcb4b4;
}

.__UIV_SCOPE__ button:disabled {
 cursor: auto;
 color: grey;
}
